    <script>
        // 全局变量
        let characterData = {};

        // 防抖函数
        function debounce(func, wait) {
            let timeout;
            return function executedFunction(...args) {
                const later = () => {
                    clearTimeout(timeout);
                    func(...args);
                };
                clearTimeout(timeout);
                timeout = setTimeout(later, wait);
            };
        }

        // 安全地获取值的函数
        function SafeGetValue(value, defaultValue = "") {
            if (value === undefined || value === null) {
                return defaultValue;
            }
            if (Array.isArray(value)) {
                return value.length > 0 ? value[0] : defaultValue;
            }
            return value;
        }

        // 初始化显示
        async function initDisplay() {
            try {
                if (typeof getCurrentMessageId !== 'function' || typeof getChatMessages !== 'function') {
                    console.warn("SillyTavern API functions not found. Using example data.");
                    characterData = getExampleData();
                    populateWithCharacterData();
                    return;
                }

                const currentMessageId = getCurrentMessageId();
                const message_data_array = await getChatMessages(currentMessageId);

                if (!message_data_array || message_data_array.length === 0) {
                    console.error("No message data returned for ID:", currentMessageId);
                    setAllFieldsToDefault();
                    return;
                }

                const gameData = message_data_array[0].data;

                if (!gameData) {
                    console.error("Message data does not contain 'data' field.");
                    setAllFieldsToDefault();
                    return;
                }

                characterData = gameData.stat_data;
                if (!characterData && gameData.display_data) {
                    console.warn("Using display_data as fallback.");
                    characterData = gameData.display_data;
                }

                if (!characterData) {
                    console.log("No character data found. Using defaults.");
                    setAllFieldsToDefault();
                    return;
                }

                populateWithCharacterData();

            } catch (error) {
                console.error("初始化显示时出错:", error);
                setAllFieldsToDefault();
            }
        }

        // 填充角色数据
        function populateWithCharacterData() {
            if (!characterData) {
                setAllFieldsToDefault();
                return;
            }

            // 更新世界状态
            updateElement('world-date', SafeGetValue(characterData["世界状态"]?.["当前日期"], "未知日期"));
            updateElement('world-weekday', SafeGetValue(characterData["世界状态"]?.["星期几"], "未知星期"));
            updateElement('world-time', SafeGetValue(characterData["世界状态"]?.["当前时间"], "未知时间"));
            updateElement('world-weather', SafeGetValue(characterData["世界状态"]?.["当前天气"], "未知天气"));

            // 更新夏白露数据
            const bailuData = characterData["角色夏白露"];
            if (bailuData) {
                updateCharacterData('bailu', bailuData);
            } else {
                setCharacterDefaults('bailu');
            }

            // 更新夏蒹葭数据
            const jianjiaData = characterData["角色夏蒹葭"];
            if (jianjiaData) {
                updateCharacterData('jianjia', jianjiaData);
            } else {
                setCharacterDefaults('jianjia');
            }
        }

        // 更新元素内容
        function updateElement(id, value) {
            const element = document.getElementById(id);
            if (element) {
                element.textContent = value;
            }
        }

        // 更新角色数据
        function updateCharacterData(prefix, data) {
            const affection = SafeGetValue(data["好感度"], 0);
            const adaptation = SafeGetValue(data["适应度"], 0);
            const mentor = SafeGetValue(data["师徒值"], 0);

            setProgress(`${prefix}-affection-value`, `${prefix}-affection-display`, `${prefix}-affection-bar`, affection);
            setProgress(`${prefix}-adaptation-value`, `${prefix}-adaptation-display`, `${prefix}-adaptation-bar`, adaptation);
            setProgress(`${prefix}-mentor-value`, `${prefix}-mentor-display`, `${prefix}-mentor-bar`, mentor);

            updateElement(`${prefix}-location`, SafeGetValue(data["当前位置"], "未知"));
            updateElement(`${prefix}-clothing`, SafeGetValue(data["当前衣着"], "未知"));
            updateElement(`${prefix}-posture`, SafeGetValue(data["当前姿势"], "未知"));
            updateElement(`${prefix}-mood`, SafeGetValue(data["当前心情"], "未知"));
            updateElement(`${prefix}-action`, SafeGetValue(data["当前行动"], "未知"));
            updateElement(`${prefix}-thought`, SafeGetValue(data["当前想法"], "未知"));
        }

        // 设置角色默认值
        function setCharacterDefaults(prefix) {
            setProgress(`${prefix}-affection-value`, `${prefix}-affection-display`, `${prefix}-affection-bar`, 0);
            setProgress(`${prefix}-adaptation-value`, `${prefix}-adaptation-display`, `${prefix}-adaptation-bar`, 0);
            setProgress(`${prefix}-mentor-value`, `${prefix}-mentor-display`, `${prefix}-mentor-bar`, 0);

            ['location', 'clothing', 'posture', 'mood', 'action', 'thought'].forEach(field => {
                updateElement(`${prefix}-${field}`, '未知');
            });
        }

        // 设置进度条
        function setProgress(valueId, displayId, barId, value, max = 1000) {
            const numericValue = typeof value === "number" ? value : parseFloat(value);

            if (isNaN(numericValue)) {
                console.warn(`setProgress received NaN for ${valueId}. Defaulting to 0.`);
                updateElement(valueId, '0');
                updateElement(displayId, `0/${max}`);
                const bar = document.getElementById(barId);
                if (bar) bar.style.width = '0%';
                return;
            }

            const percentage = Math.min((numericValue / max) * 100, 100);

            updateElement(valueId, numericValue.toString());
            updateElement(displayId, `${numericValue}/${max}`);

            const bar = document.getElementById(barId);
            if (bar) {
                requestAnimationFrame(() => {
                    bar.style.width = `${percentage}%`;
                });
            }

            const progressBar = bar?.parentElement;
            if (progressBar) {
                progressBar.setAttribute('aria-valuenow', numericValue.toString());
            }
        }

        // 设置所有字段为默认值
        function setAllFieldsToDefault() {
