        };

        // 切换章节显示
        const debouncedToggleSection = debounce(function(sectionType) {
            sectionStates[sectionType] = !sectionStates[sectionType];
            const isExpanded = sectionStates[sectionType];

            ['bailu', 'jianjia'].forEach(character => {
                updateSectionState(character, sectionType, isExpanded);
            });
        }, 100);

        function toggleSection(sectionType) {
            debouncedToggleSection(sectionType);
        }

        // 更新章节状态
        function updateSectionState(character, sectionType, isExpanded) {
            const content = document.getElementById(`${character}-${sectionType}-content`);
            const chevron = document.getElementById(`${character}-${sectionType}-chevron`);
            const header = chevron?.closest('.section-header');
            const section = header?.closest('.section');

            if (content && chevron && header && section) {
                if (isExpanded) {
                    content.classList.add('expanded');
                    chevron.classList.add('expanded');
                    section.classList.add('expanded');
                    header.setAttribute('aria-expanded', 'true');
                } else {
                    content.classList.remove('expanded');
                    chevron.classList.remove('expanded');
                    section.classList.remove('expanded');
                    header.setAttribute('aria-expanded', 'false');
